class Qwen3_5Cache(KVCache, GatedDeltaCache):
    """Hybrid cache combining full-attention K/V and Gated Delta states.

    Parameters:
        None.
    """

    def __init__(self) -> None:
        """Initialize all source cache state dictionaries.

        Parameters:
            None.
        """
        KVCache.__init__(self)
        GatedDeltaCache.__init__(self)
        self.sequence_length = 0

    def get_seq_length(self, layer_idx: int | None = None) -> int:
        """Return global sequence length or the requested full-attention layer length.

        Parameters:
            layer_idx: Full-attention layer index, or ``None`` for global length.
        """
        if layer_idx is None:
            return self.sequence_length
        return KVCache.get_seq_length(self, layer_idx)


class Qwen3_5RMSNorm(nn.Module):
    """Official Qwen3.5 RMSNorm whose weight is centered around one.

    Parameters:
        dim: Hidden-state dimension.
        eps: Numerical stability constant.
    """

    def __init__(self, dim: int, eps: float = 1e-6) -> None:
        """Create the zero-centered RMSNorm parameter.

        Parameters:
            dim: Hidden-state dimension.
            eps: Numerical stability constant.
        """
        super().__init__()
        self.eps = eps
        self.weight = nn.Parameter(torch.zeros(dim))

    def _norm(self, hidden_states: torch.Tensor) -> torch.Tensor:
        """Compute RMS normalization in float32.

        Parameters:
            hidden_states: Tensor to normalize.
        """
        return hidden_states * torch.rsqrt(hidden_states.pow(2).mean(-1, keepdim = True) + self.eps)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        """Normalize using the official ``(1 + weight)`` scale convention.

        Parameters:
            hidden_states: Tensor whose final dimension equals the norm size.
        """
        output = self._norm(hidden_states.float())
        # Llama does x.to(float16) * w whilst Qwen3_5 is (x * w).to(float16)
        # See https://github.com/huggingface/transformers/pull/29402
        return (output * (1.0 + self.weight.float())).type_as(hidden_states)


class Qwen3_5RotaryEmbedding(nn.Module):
    """Static partial rotary embedding used by Qwen3.5 full-attention layers.

    Parameters:
        config: Qwen3.5 text configuration.
    """

    def __init__(self, config: Qwen3_5TextConfig) -> None:
        """Create Qwen3.5 partial-RoPE inverse frequencies.

        Parameters:
            config: Qwen3.5 text configuration.
        """
        super().__init__()
        self.rotary_dim = int(config.head_dim * config.rope_parameters.get("partial_rotary_factor", 1.0))
        self.rotary_dim -= self.rotary_dim % 2
        theta = config.rope_parameters.get("rope_theta", 1000000.0)
        inv_freq = 1.0 / (theta ** (torch.arange(0, self.rotary_dim, 2, dtype = torch.float32) / self.rotary_dim))
        self.register_buffer("inv_freq", inv_freq, persistent = False)

    def forward(
        self,
        hidden_states: torch.Tensor,
        position_ids: torch.Tensor,
    ) -> tuple[torch.Tensor, torch.Tensor]:
        """Generate partial rotary cosine and sine values.

        Parameters:
            hidden_states: States supplying output device and dtype.
            position_ids: Absolute text positions shaped ``[batch, sequence]``.
        """
        frequencies = torch.einsum(
            "d,bs->bsd",
            self.inv_freq.to(hidden_states.device),
            position_ids.to(torch.float32),
        )
        embeddings = torch.cat((frequencies, frequencies), dim = -1)
        return embeddings.cos().to(hidden_states.dtype), embeddings.sin().to(hidden_states.dtype)


def rotate_half(hidden_states: torch.Tensor) -> torch.Tensor:
    """Rotates half the hidden dims of the input.

    Parameters:
        hidden_states: Tensor with an even final rotary dimension.
    """
    first_half = hidden_states[..., : hidden_states.shape[-1] // 2]
    second_half = hidden_states[..., hidden_states.shape[-1] // 2 :]
    return torch.cat((-second_half, first_half), dim = -1)


def apply_rotary_pos_emb(
    query_states: torch.Tensor,
    key_states: torch.Tensor,
    cos: torch.Tensor,
    sin: torch.Tensor,
) -> tuple[torch.Tensor, torch.Tensor]:
    """Apply Qwen3.5 partial RoPE without GLM cos/sin interleaving.

    Parameters:
        query_states: Query states shaped ``[batch, heads, tokens, head_dim]``.
        key_states: Key states shaped ``[batch, kv_heads, tokens, head_dim]``.
        cos: Rotary cosine values.
        sin: Rotary sine values.
    """
    cos, sin = cos.unsqueeze(1), sin.unsqueeze(1)
    rotary_dim = cos.shape[-1]
    query_rot, query_pass = query_states[..., :rotary_dim], query_states[..., rotary_dim:]
    key_rot, key_pass = key_states[..., :rotary_dim], key_states[..., rotary_dim:]
    query_embed = query_rot * cos + rotate_half(query_rot) * sin
    key_embed = key_rot * cos + rotate_half(key_rot) * sin
    return torch.cat([query_embed, query_pass], dim = -1), torch.cat([key_embed, key_pass], dim = -1)


class Qwen3_5Attention(nn.Module):
    """Official Qwen3.5 full attention with a post-attention sigmoid gate.

    Parameters:
        config: Qwen3.5 text configuration.
        layer_idx: Decoder layer index used by the K/V cache.
    """

    def __init__(self, config: Qwen3_5TextConfig, layer_idx: int) -> None:
        """Create official gated-Q and GQA projection matrices.

        Parameters:
            config: Qwen3.5 text configuration.
            layer_idx: Decoder layer index.
        """
        super().__init__()
        self.config = config
        self.layer_idx = layer_idx
        self.head_dim = config.head_dim
        self.num_key_value_groups = config.num_attention_heads // config.num_key_value_heads
        self.scaling = self.head_dim**-0.5
        self.q_proj = nn.Linear(config.hidden_size, config.num_attention_heads * self.head_dim * 2, bias = config.attention_bias)
        self.k_proj = nn.Linear(config.hidden_size, config.num_key_value_heads * self.head_dim, bias = config.attention_bias)
        self.v_proj = nn.Linear(config.hidden_size, config.num_key_value_heads * self.head_dim, bias = config.attention_bias)
        self.o_proj = nn.Linear(config.num_attention_heads * self.head_dim, config.hidden_size, bias = config.attention_bias)
        self.q_norm = Qwen3_5RMSNorm(self.head_dim, eps = config.rms_norm_eps)  # unlike olmo, only on the head dim!
        self.k_norm = Qwen3_5RMSNorm(self.head_dim, eps = config.rms_norm_eps)  # thus post q_norm does not need reshape

    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: torch.Tensor | None,
        past_key_values: Qwen3_5Cache | None,
        use_cache: bool,
    ) -> torch.Tensor:
        """Compute the source full-attention token mixer.

        Parameters:
            hidden_states: Input hidden states.
            position_embeddings: Partial RoPE cosine and sine tensors.
            attention_mask: Optional valid-key padding mask.
            past_key_values: Optional hybrid recurrent/KV cache.
            use_cache: Whether K/V cache states are updated.
        """
        batch_size, query_length, _ = hidden_states.shape
        query_and_gate = self.q_proj(hidden_states).view(batch_size, query_length, -1, self.head_dim * 2)
        query_states, gate = torch.chunk(query_and_gate, 2, dim = -1)
        gate = gate.reshape(batch_size, query_length, -1)
        query_states = self.q_norm(query_states).transpose(1, 2)
        key_states = self.k_norm(self.k_proj(hidden_states).view(batch_size, query_length, -1, self.head_dim)).transpose(1, 2)
        value_states = self.v_proj(hidden_states).view(batch_size, query_length, -1, self.head_dim).transpose(1, 2)
        query_states, key_states = apply_rotary_pos_emb(query_states, key_states, *position_embeddings)
        past_length = 0
        if past_key_values is not None:
            past_length = past_key_values.get_seq_length(self.layer_idx)
            if use_cache:
                key_states, value_states = past_key_values.update(key_states, value_states, self.layer_idx)
        key_states = repeat_kv(key_states, self.num_key_value_groups)
        value_states = repeat_kv(value_states, self.num_key_value_groups)
        mask = build_attention_mask(
            attention_mask = attention_mask,
            query_length = query_length,
            key_length = key_states.shape[-2],
            past_length = past_length,
            layer_type = "full_attention",
            sliding_window = None,
            device = hidden_states.device,
            dtype = query_states.dtype,
        )
        weights = torch.matmul(query_states, key_states.transpose(-2, -1)) * self.scaling + mask
        weights = F.softmax(weights, dim = -1, dtype = torch.float32).to(query_states.dtype)
        output = torch.matmul(weights, value_states).transpose(1, 2).reshape(batch_size, query_length, -1).contiguous()
        return self.o_proj(output * torch.sigmoid(gate))


class Qwen3_5MLP(nn.Module):
    """Official Qwen3.5 SwiGLU MLP.

    Parameters:
        config: Qwen3.5 text configuration.
    """

    def __init__(self, config: Qwen3_5TextConfig) -> None:
        """Create gate, up, and down projections.

        Parameters:
            config: Qwen3.5 text configuration.
        """
        super().__init__()
        self.gate_proj = nn.Linear(config.hidden_size, config.intermediate_size, bias = False)
        self.up_proj = nn.Linear(config.hidden_size, config.intermediate_size, bias = False)
        self.down_proj = nn.Linear(config.intermediate_size, config.hidden_size, bias = False)

    def forward(self, hidden_states: torch.Tensor) -> torch.Tensor:
        """Apply the Qwen3.5 SwiGLU transformation.

        Parameters:
            hidden_states: Decoder token states.
        """
        return self.down_proj(F.silu(self.gate_proj(hidden_states)) * self.up_proj(hidden_states))


class Qwen3_5DecoderLayer(nn.Module):
    """Official hybrid Qwen3.5 decoder layer.

    Parameters:
        config: Qwen3.5 text configuration.
        layer_idx: Decoder layer index.
    """

    def __init__(self, config: Qwen3_5TextConfig, layer_idx: int) -> None:
        """Create the configured Gated Delta or full-attention token mixer.

        Parameters:
            config: Qwen3.5 text configuration.
            layer_idx: Decoder layer index.
        """
        super().__init__()
        self.block_type = config.layer_types[layer_idx]
        if self.block_type == "linear_attention":
            self.linear_attn = GatedDeltaNet(config, layer_idx)
        elif self.block_type == "full_attention":
            self.self_attn = Qwen3_5Attention(config, layer_idx)
        else:
            raise ValueError(f"Unsupported Qwen3.5 layer type: {self.block_type}")
        self.mlp = Qwen3_5MLP(config)
        self.input_layernorm = Qwen3_5RMSNorm(config.hidden_size, eps = config.rms_norm_eps)
        self.post_attention_layernorm = Qwen3_5RMSNorm(config.hidden_size, eps = config.rms_norm_eps)

    def forward(
        self,
        hidden_states: torch.Tensor,
        position_embeddings: tuple[torch.Tensor, torch.Tensor],
        attention_mask: torch.Tensor | None,
        past_key_values: Qwen3_5Cache | None,
        use_cache: bool,
    ) -> torch.Tensor:
        """Apply the source token mixer and feed-forward residual sublayers.

        Parameters:
            hidden_states: Decoder input states.
            position_embeddings: Partial RoPE values for full-attention layers.
            attention_mask: Optional valid-token mask.
            past_key_values: Optional hybrid cache.
            use_cache: Whether cache state is updated.
        """
        residual = hidden_states
        hidden_states = self.input_layernorm(hidden_states)
        # Token Mixer
        if self.block_type == "linear_attention":
            hidden_states = self.linear_attn(hidden_states, past_key_values, attention_mask)
        else:
            hidden_states = self.self_attn(hidden_states, position_embeddings, attention_mask, past_key_values, use_cache)
        hidden_states = residual + hidden_states
        # Fully Connected
        return hidden_states + self.mlp(self.post_attention_layernorm(hidden_states))


class Qwen3_5TextModel(nn.Module):
    """Framework-independent Qwen3.5 text model retaining its hybrid layer schedule.

    Parameters:
        config: Qwen3.5 text configuration.
    """

    def __init__(self, config: Qwen3_5TextConfig) -> None:
        """Create embeddings, hybrid decoder layers, final norm, and RoPE.

        Parameters:
            config: Qwen3.5 text configuration.
        """
        super().__init__()
        self.config = config
        self.embed_tokens = nn.Embedding(config.vocab_size, config.hidden_size, config.pad_token_id)
        self.layers = nn.ModuleList([Qwen3_5DecoderLayer(config, index) for index in range(config.num_hidden_layers)])
        self.norm = Qwen3_5RMSNorm(config.hidden_size, eps = config.rms_norm_eps)
        self.rotary_emb = Qwen3_5RotaryEmbedding(config)

    def forward(
        self,
        input_ids: torch.Tensor | None = None,
        attention_mask: torch.Tensor | None = None,
        past_key_values: Qwen3_5Cache | None = None,
        inputs_embeds: torch.Tensor | None = None,
        use_cache: bool | None = None,
    ) -> tuple[torch.Tensor, Qwen3_5Cache | None]:
        """Return final text hidden states and optional hybrid cache.

        Parameters:
            input_ids: Token IDs, mutually exclusive with ``inputs_embeds``.
            attention_mask: Optional valid-token mask.
            past_key_values: Optional hybrid cache from an earlier forward call.
            inputs_embeds: Precomputed token embeddings.
            use_cache: Whether cache states are created and updated.
        """
        if (input_ids is None) == (inputs_embeds is None):
            raise ValueError("You must specify exactly one of input_ids or inputs_embeds")
        use_cache = self.config.use_cache if use_cache is None else use_cache
        if inputs_embeds is None:
            inputs_embeds = self.embed_tokens(input_ids)
        if use_cache and past_key_values is None:
            past_key_values = Qwen3_5Cache()
        past_length = past_key_values.get_seq_length() if past_key_values is not None else 0
        position_ids = torch.arange(past_length, past_length + inputs_embeds.shape[1], device = inputs_embeds.device)
        position_ids = position_ids.unsqueeze(0).expand(inputs_embeds.shape[0], -1)
        position_embeddings = self.rotary_emb(inputs_embeds, position_ids)
        hidden_states = inputs_embeds
        for layer in self.layers:
            hidden_states = layer(hidden_states, position_embeddings, attention_mask, past_key_values, use_cache)
        if past_key_values is not None and use_cache:
            past_key_values.sequence_length += inputs_embeds.shape[1]
        return self.norm(hidden_states), past_key_values if use_cache else None


class Qwen3_5ForCausalLM(nn.Module):
    """Qwen3.5 causal LM exposing logits, CE loss, and hybrid cache.

    Parameters:
        config: Qwen3.5 text configuration.
    """

    def __init__(self, config: Qwen3_5TextConfig) -> None:
        """Create the source hybrid decoder and untied language-model head.

        Parameters:
            config: Qwen3.5 text configuration.
        """
        super().__init__()
        self.config = config
        self.model = Qwen3_5TextModel(config)
        self.lm_head = nn.Linear(config.hidden_size, config.vocab_size, bias = False)
        self.apply(self._init_weights)

    def _init_weights(self, module: nn.Module) -> None:
        """Apply the source normal initialization and zero-centered norm setup.

        Parameters:
            module: Module visited during recursive initialization.
        """
        if isinstance(module, (nn.Linear, nn.Embedding, nn.Conv1d)):
            nn.init.normal_(module.weight, mean = 0.0, std = self.config.initializer_range)
            if getattr(module, "bias", None) is not None:
                nn.init.zeros_(module.bias)
        elif isinstance(module, Qwen3_5RMSNorm):
            # We initialize with 0s to be 1 centered as the RMSNorm here does (1 + weight)
            nn.init.zeros_(module.weight)
        elif isinstance(module, GatedDeltaNet):
            nn.init.ones_(module.dt_bias)

    def forward(
        self,
        input_ids: torch.Tensor,
        attention_mask: torch.Tensor | None = None,
        past_key_values: Qwen3_5Cache | None = None,
        use_cache: bool | None = None,
        labels: torch.Tensor | None = None,
    ) -> Qwen3CausalLMOutput:
        """Return logits, optional CE loss, and source hybrid cache states.

        Parameters:
            input_ids: Text token IDs.
            attention_mask: Optional valid-token mask.
            past_key_values: Optional hybrid cache.
            use_cache: Whether cache states are returned.
            labels: Optional shifted language-model targets.
        """
        hidden_states, cache = self.model(input_ids, attention_mask, past_key_values, use_cache = use_cache)
        logits = self.lm_head(hidden_states)
        loss = None
        if labels is not None:
            loss = F.cross_entropy(logits[:, :-1].reshape(-1, self.config.vocab_size), labels[:, 1:].reshape(-1), ignore_index = -100)
        return Qwen3CausalLMOutput(logits = logits, loss = loss, past_key_values = cache)


